seedFiles.components/Testimonials.tsx:
const QUOTES = [
  { name: 'Anjali Rao', text: 'The filter coffee is the best in Bengaluru.' },
  { name: 'Vikram Nair', text: 'I come here every morning before work.' },
];

export default function Testimonials() {
  return (
    <section className="bg-card px-6 py-20">
      <h2 className="text-3xl font-semibold text-foreground">What people say</h2>
      <div className="mt-8 grid gap-6 md:grid-cols-2">
        {QUOTES.map((quote) => (
          <figure key={quote.name} className="rounded-lg border border-border p-6">
            <blockquote className="text-muted-foreground">{quote.text}</blockquote>
            <figcaption className="mt-4 text-sm text-foreground">{quote.name}</figcaption>
          </figure>
        ))}
      </div>
    </section>
  );
}

